#!/bin/bash
set -euo pipefail
# ============================================================================
# Bring up the WireGuard mesh between Server 1 and Server 2. Reads each node's
# public key (generated by provision-node.sh), renders wg0.conf from the
# templates, installs it, and starts wg-quick@wg0. Idempotent.
#
# Public endpoints: resolved from SSH_SERVER* hosts (strip the user@ prefix).
# ============================================================================
HERE="$(cd "$(dirname "$0")" && pwd)"
REPO="$(cd "$HERE/../.." && pwd)"
ENV_FILE="${ENV_FILE:-$REPO/.env}"
WGDIR="$REPO/ha/wireguard"

getenv() { python3 - "$1" "$ENV_FILE" <<'PY'
import re,sys
k,f=sys.argv[1],sys.argv[2]
m=re.search(r'^'+re.escape(k)+r'=(.*)$',open(f).read(),re.M)
v=m.group(1).strip() if m else ''
if len(v)>=2 and v[0]==v[-1] and v[0] in '"\'': v=v[1:-1]
print(v)
PY
}
S1="$(getenv SSH_SERVER)";  S1_PWD="$(getenv SSH_SERVER_PWD)"
S2="$(getenv SSH_SERVER2)"; S2_PWD="$(getenv SSH_SERVER2_PWD)"
s1() { sshpass -p "$S1_PWD" ssh -o StrictHostKeyChecking=accept-new "$S1" "$@"; }
s2() { sshpass -p "$S2_PWD" ssh -o StrictHostKeyChecking=accept-new "$S2" "$@"; }
# Public endpoint = host portion after user@ (SSH_SERVER="root@host").
EP1="${S1#*@}"; EP2="${S2#*@}"

PUB1="$(s1 'cat /etc/wireguard/publickey')"
PRIV1="$(s1 'cat /etc/wireguard/privatekey')"
PUB2="$(s2 'cat /etc/wireguard/publickey')"
PRIV2="$(s2 'cat /etc/wireguard/privatekey')"

render() { # template privkey peerpub peerendpoint
  sed -e "s|__SRV1_PRIVATE_KEY__|$2|g" -e "s|__SRV2_PRIVATE_KEY__|$2|g" \
      -e "s|__SRV1_PUBLIC_KEY__|$3|g"  -e "s|__SRV2_PUBLIC_KEY__|$3|g" \
      -e "s|__SRV1_PUBLIC_ENDPOINT__|$4|g" -e "s|__SRV2_PUBLIC_ENDPOINT__|$4|g" "$1"
}

CONF1="$(render "$WGDIR/wg0.server1.conf.template" "$PRIV1" "$PUB2" "$EP2")"
CONF2="$(render "$WGDIR/wg0.server2.conf.template" "$PRIV2" "$PUB1" "$EP1")"

echo "== installing wg0.conf + starting tunnel on Server 1 =="
printf '%s\n' "$CONF1" | s1 'umask 077; cat > /etc/wireguard/wg0.conf; systemctl enable wg-quick@wg0 >/dev/null 2>&1 || true; (wg-quick down wg0 2>/dev/null || true); wg-quick up wg0; wg show'
echo "== installing wg0.conf + starting tunnel on Server 2 =="
printf '%s\n' "$CONF2" | s2 'umask 077; cat > /etc/wireguard/wg0.conf; systemctl enable wg-quick@wg0 >/dev/null 2>&1 || true; (wg-quick down wg0 2>/dev/null || true); wg-quick up wg0; wg show'

echo "== verify handshake =="
s1 'ping -c2 -W2 10.88.0.2 && echo "srv1 → srv2 OK"'
s2 'ping -c2 -W2 10.88.0.1 && echo "srv2 → srv1 OK"'
echo "✅ WireGuard mesh up (10.88.0.1 ⇄ 10.88.0.2)."
